export const U32Order = {
    name: 'u32 order',
    type: U32Type,
    compare(a, b) {
        return a - b;
    },
    getBits: (value, bitOffset, bitQuantity) => {
        return ((value >>> bitOffset) & ((1 << bitQuantity) - 1)) >>> 0;
    },
    compareWGSL: (a, b) => {
        // TODO: THIS FAILS RANGE CHECKS
        // return `( i32( ${a} ) - i32( ${b} ) )`;
        return wgsl `select( select( 0i, 1i, ${a} > ${b} ), -1i, ${a} < ${b} )`;
    },
    greaterThanWGSL: (a, b) => {
        return wgsl `( ${a} > ${b} )`;
    },
    lessThanOrEqualWGSL: (a, b) => {
        return wgsl `( ${a} <= ${b} )`;
    },
    getBitsWGSL: (value, bitOffset, bitQuantity) => {
        return wgsl `( ( ${value} >> ${u32S(bitOffset)} ) & ${u32S((1 << bitQuantity) - 1)} )`;
    }
};
export const U32ReverseOrder = {
    name: 'u32 reverse order',
    type: U32Type,
    compare(a, b) {
        return b - a;
    },
    getBits: (value, bitOffset, bitQuantity) => {
        return (((0xffffffff - value) >>> bitOffset) & ((1 << bitQuantity) - 1)) >>> 0;
    },
    compareWGSL: (a, b) => {
        return wgsl `select( select( 0i, 1i, ${a} < ${b} ), -1i, ${a} > ${b} )`;
    },
    greaterThanWGSL: (a, b) => {
        return wgsl `( ${a} < ${b} )`;
    },
    lessThanOrEqualWGSL: (a, b) => {
        return wgsl `( ${a} >= ${b} )`;
    },
    getBitsWGSL: (value, bitOffset, bitQuantity) => {
        // TODO: is there a bitwise trick?
        return wgsl `( ( ( 0xffffffffu - ${value} ) >> ${u32S(bitOffset)} ) & ${u32S((1 << bitQuantity) - 1)} )`;
    }
};
