export const Vec2uType = {
    name: 'vec2u',
    bytesPerElement: 8,
    outOfRangeElement: new Vector2(101010101, 101010101),
    equals(a, b) {
        return a.equals(b);
    },
    equalsWGSL: (a, b) => {
        // TODO: test
        return wgsl `all( ${a} == ${b} )`;
    },
    encode(value, encoder) {
        encoder.pushU32(value.x);
        encoder.pushU32(value.y);
    },
    decode(encoder, offset) {
        return new Vector2(encoder.fullU32Array[offset], encoder.fullU32Array[offset + 1]);
    },
    valueType: wgsl `vec2u`,
    writeU32s(storeStatement, value) {
        return wgsl `
       ${storeStatement(wgsl `0u`, wgsl `${value}.x`)}
       ${storeStatement(wgsl `1u`, wgsl `${value}.y`)}
    `;
    },
    wgslAlign: 8,
    wgslSize: 8,
    generateRandom: (fullSize = false) => new Vector2(U32Type.generateRandom(fullSize), U32Type.generateRandom(fullSize)),
    toDebugString: (value) => `vec2u(${value.x}, ${value.y})`
};
